"""Unique Paths II — same rolling row, obstacles zero the cell out.

Time: O(m*n)   Space: O(n)
"""
from typing import List


class Solution:
    def uniquePathsWithObstacles(self, obstacleGrid: List[List[int]]) -> int:
        n = len(obstacleGrid[0])
        row = [0] * n
        row[0] = 1
        for line in obstacleGrid:
            for j in range(n):
                if line[j] == 1:
                    row[j] = 0
                elif j:
                    row[j] += row[j - 1]
        return row[-1]
